    readonly config = createGameConfig();
    private readonly gameplay = new JumpGameplay(this.config);
    private readonly clock = new FixedTickClock(this.config);
    private adapter: InputAdapter | null = null;
    private pool: PlatformPool | null = null;
    private camera: CameraFollow | null = null;
    private avatarView: AvatarView | null = null;
    private previousFoot: FootPosition = { x: 0, y: 0, z: 0 };
    private inputs: ReplayInput[] = [];
    private counts = { jumps: 0, scored: 0, failed: 0 };
    private autoReplay = false;
    private autoHoldTicks = 0;
    private initialized = false;
    private recenterJump = 0;
    private readonly calibrationPlatforms: Node[] = [];

    start(): void {
        if (!this.world || !this.avatar || !this.worldCamera || !this.uiRoot || !this.currentPlatformPrefab ||
            !this.targetPlatformPrefab || !this.circlePlatformPrefab || !this.backgroundTexture ||
            this.coreModelPrefabs.length !== this.config.modelKeys.length || !this.numberFont || !this.singlePlayerUI ||
            !this.chargeIntro || !this.chargeLoop || !this.successClip || !this.fallClip || !this.startClip || this.comboClips.length !== 8 ||
            !this.gradient || this.backgroundTextures.length !== 7) throw new Error('JumpMain phase04 references incomplete');
        this.audio = new AudioAdapter(this.node, { intro: this.chargeIntro, loop: this.chargeLoop, success: this.successClip,
            combos: this.comboClips, fall: this.fallClip, start: this.startClip });
        this.avatarView = this.avatar.getComponent(AvatarView);
        if (!this.avatarView) throw new Error('stage01 AvatarView missing');
        // Keep editable stage01 calibration instances; the runtime pool owns playable platforms.
        for (const child of this.world.children) if (child !== this.avatar && child.getComponent('PlatformView')) {
            this.calibrationPlatforms.push(child); child.active = false;
        }
        this.pool = new PlatformPool(this.world, this.currentPlatformPrefab, this.targetPlatformPrefab, this.circlePlatformPrefab,
            this.coreModelPrefabs, this.config.modelKeys, this.config.platformPoolLimit);
        this.gameplay.start();
        this.initialPlatforms.push(this.gameplay.current!, this.gameplay.target!);
        this.camera = new CameraFollow(this.worldCamera, Math.ceil(this.config.cameraMoveSeconds / this.config.fixedStepSeconds), this.gameplay.current!, this.gameplay.target!);
        this.adapter = new InputAdapter({
            press: source => this.press(source), release: source => { this.release(source); },
            cancel: (source, reason) => { this.record('cancel', source || 'system'); this.gameplay.cancel(source, reason); this.consumeEvents(); },
            pause: reason => this.pause(reason), command: key => this.command(key),
            blocked: () => this.transitionSeconds > 0 || this.autoReplay || ['menu', 'paused', 'gameover'].indexOf(this.gameplay.state.phase) >= 0,
        }, this.uiRoot);
        this.adapter.bind();
        this.storage = new StorageAdapter(sys.localStorage);
        this.singlePlayerUI.connect({ start: () => this.activateRun(), pause: () => this.uiAction(() => this.pause('player')),
            resume: () => this.uiAction(() => this.resume()), restart: () => this.activateRun(), home: () => this.uiAction(() => this.goHome()) });
        profiler.hideStats();
        this.initialized = true; this.goHome();
    }
    onEnable(): void { if (this.initialized) this.adapter?.bind(); }
    onDisable(): void { this.adapter?.unbind(); if (this.initialized) this.pause('disabled'); }
    onDestroy(): void {
        this.adapter?.unbind(); this.pool?.destroy(); this.audio?.destroy();
        this.singlePlayerUI?.disconnect();
        this.unscheduleAllCallbacks();
        const bridge = this.bridge();
        for (const key of ['jump', 'jumpPlatforms', 'jumpResults', 'jumpInputs', 'jumpView', 'jumpUI', 'jumpAudio', 'jumpAudioEngine', 'jumpAudioEvents']) bridge?.clearState?.(key);
    }
    update(delta: number): void {
        if (!this.initialized) return;
        if (this.transitionSeconds > 0) {
            this.transitionSeconds = Math.max(0, this.transitionSeconds - delta);
            if (this.transitionSeconds === 0) this.singlePlayerUI?.setLocked(false);
        }
        const frame = this.clock.advanceFrame(delta, () => {
            this.previousFoot = this.gameplay.foot;
            if (this.autoReplay) this.replayInput();
            this.gameplay.step(); this.consumeEvents();
        });
        if (frame.freezeReason === 'backlog' && this.gameplay.state.phase !== 'paused') this.pause('simulation-backlog');
        this.render(frame.interpolationAlpha); this.publish();
    }
    private press(source: string): boolean {
        if (source !== 'replay') this.audio?.enableFromGesture();
        this.record('press', source); const accepted = this.gameplay.press(source); this.consumeEvents(); return accepted;
    }
    private release(source: string): void { this.record('release', source); this.gameplay.release(source); this.consumeEvents(); }
    private pause(reason: string): void {
        if (!this.gameplay.pause(reason)) return;
        this.record('pause', reason); this.clock.pause(); this.adapter?.reset(); this.consumeEvents();
        this.render(0); this.publish();
    }
    private resume(): void {
        if (!this.gameplay.resume()) return;
        this.record('resume', 'control'); this.clock.resume(); this.consumeEvents();
    }
    private togglePause(): void { if (this.gameplay.state.phase === 'paused') this.resume(); else this.pause('player'); }
    private uiAction(action: () => void): void {
        if (this.transitionSeconds > 0) return;
        this.lockUI(); action(); this.render(0); this.publish();
    }
    private lockUI(): void { this.uiGeneration++; this.transitionSeconds = 0.18; this.singlePlayerUI?.setLocked(true); }
    private activateRun(): void { this.audio?.enableFromGesture(); this.uiAction(() => this.newRun()); }
    private cleanupRun(): void {
        this.uiGeneration++; this.unscheduleAllCallbacks(); this.autoReplay = false; this.fixtureFail = false;
        this.audio?.stopAll(); this.audioEvents = [];
        this.adapter?.reset(); this.pool?.clear();
        if (this.avatarView?.visual) Tween.stopAllByTarget(this.avatarView.visual);
        this.inputs = []; this.counts = { jumps: 0, scored: 0, failed: 0 }; this.recenterJump = 0;
    }
    private goHome(): void {
        this.cleanupRun(); this.gameplay.home(); this.audio?.reset(this.gameplay.state.runId); this.clock.reset(); this.clock.pause();
        // Restore saved editable calibration nodes, not a second game/controller.
        for (const child of this.calibrationPlatforms) child.active = child.name !== 'PlatformCircle03';
        this.avatarView?.render({ x: 0, y: this.config.platformHeight, z: 0 }, 0, null, this.config.platformHeight);
        this.camera?.reset(this.initialPlatforms[0], this.initialPlatforms[1]);
        this.render(0); this.publish();
    }
    private readonly initialPlatforms: PlatformSpec[] = [];
    private newRun(): void {
        this.cleanupRun(); this.clock.reset();
        this.restartCount++;
        for (const child of this.calibrationPlatforms) child.active = false;
        this.gameplay.start(this.config.seed); this.audio?.reset(this.gameplay.state.runId); this.previousFoot = this.gameplay.foot;
        this.camera?.reset(this.gameplay.current!, this.gameplay.target!);
        this.pool?.sync(this.gameplay.platforms); this.consumeEvents(); this.render(0); this.publish();
    }
    private command(key: KeyCode): void {
        this.audio?.enableFromGesture();
        if (key === KeyCode.KEY_P) this.uiAction(() => this.togglePause());
        else if (key === KeyCode.KEY_R && this.gameplay.state.phase !== 'menu') this.activateRun();
        else if (key === KeyCode.ESCAPE) this.uiAction(() => this.goHome());
        else if (DEBUG && key === KeyCode.F7) game.emit(Game.EVENT_HIDE);
        else if (DEBUG && key === KeyCode.F8) { this.storage?.reset(); this.render(0); this.publish(); }
        else if (DEBUG && (key === KeyCode.F9 || key === KeyCode.F10)) {
            this.uiAction(() => { this.newRun(); this.autoReplay = true; this.fixtureFail = key === KeyCode.F10; this.publish(); });
        }
    }
    /** Developer fixture uses only ordinary press/release with integer ticks; no position/score setters. */
    private replayInput(): void {
        if (this.gameplay.state.phase === 'ready') {
            if (this.fixtureFail && this.counts.scored >= 1) {
                this.autoHoldTicks = Math.ceil(this.config.minChargeSeconds / this.config.fixedStepSeconds);
                this.press('replay'); return;
            }
            if (this.counts.scored >= 24) {
                this.autoReplay = false; this.pause('replay-complete'); this.bridge()?.checkpoint?.('phase02-24-jumps'); return;
            }
            const foot = this.gameplay.foot, target = this.gameplay.target!;
            const distance = Math.hypot(target.centerXZ.x - foot.x, target.centerXZ.z - foot.z);
            const seconds = this.config.minChargeSeconds + (distance - this.config.minJumpDistance) /
                (this.config.maxJumpDistance - this.config.minJumpDistance) * (this.config.maxChargeSeconds - this.config.minChargeSeconds);
            this.autoHoldTicks = Math.round(seconds / this.config.fixedStepSeconds); this.press('replay');
        } else if (this.gameplay.state.phase === 'charging' &&
            this.gameplay.state.tick - this.gameplay.state.chargeStartTick! >= this.autoHoldTicks) this.release('replay');
    }
    private consumeEvents(): void {
        for (const event of this.gameplay.drainEvents()) {
            this.audio?.consume(event, this.gameplay.state.runId);
            if ((event.type === 'Scored' || event.type === 'Failed') && event.runId === this.gameplay.state.runId && this.audio) {
                const audio = this.audio.snapshot();
                this.audioEvents.push({ runId: event.runId, jumpId: event.jumpId, type: event.type,
                    feedback: audio.feedback, combo: audio.combo, playRequests: audio.playRequests });
                this.audioEvents = this.audioEvents.slice(-16);
            }
            if (event.runId !== this.gameplay.state.runId) continue;
            if (event.type === 'Jump') this.counts.jumps++;
            else if (event.type === 'Scored') this.counts.scored++;
            else if (event.type === 'Failed') {
                this.counts.failed++; this.autoReplay = false;
                if (this.finalRun !== event.runId) { this.finalRun = event.runId; this.storage?.record(this.gameplay.state.score); this.lockUI(); }
                this.bridge()?.checkpoint?.('phase03-gameover');
            }
        }
        if (this.gameplay.state.phase === 'recentering' && this.gameplay.state.jumpId !== this.recenterJump) {
            const landed = this.gameplay.target!, next = this.gameplay.platforms.find(s => s.id === landed.id + 1)!;
            this.camera?.begin(this.gameplay.state.tick, landed, next); this.recenterJump = this.gameplay.state.jumpId!;
        }
        this.pool?.sync(this.gameplay.platforms);
    }
    private render(alpha: number): void {
        const state = this.gameplay.state;
        this.singlePlayerUI?.render(state.phase, state.score, this.storage?.best || 0, this.counts.jumps === 0, this.storage?.lastError || null);
        if (state.phase === 'menu') return;
        const phase = state.phase === 'paused' ? state.resumePhase : state.phase;
        let foot = this.gameplay.foot;
        let flight: number | null = null;
        if (phase === 'airborne' && state.jumpPlan) {
            const elapsed = Math.max(0, (state.tick - state.jumpPlan.startTick - 1 + alpha) * this.config.fixedStepSeconds);
            foot = sampleJump(state.jumpPlan, elapsed, this.config); flight = elapsed / state.jumpPlan.flightTime;
        } else if (phase === 'falling' && state.jumpPlan) {
            const elapsed = (state.tick - state.jumpPlan.startTick) * this.config.fixedStepSeconds;
            foot = { ...foot, y: state.jumpPlan.startFoot.y + this.config.verticalVelocity * elapsed - this.config.gravity * elapsed * elapsed / 2 };
        } else if (state.phase !== 'paused') {
            const a = this.previousFoot, b = foot;
            foot = { x: a.x + (b.x - a.x) * alpha, y: a.y + (b.y - a.y) * alpha, z: a.z + (b.z - a.z) * alpha };
        }
        const q = this.gameplay.holdSeconds / this.config.maxChargeSeconds;
        this.avatarView?.render(foot, q, flight, this.gameplay.current?.topY || this.config.platformHeight);
        this.camera?.render(state.tick, state.phase === 'paused' ? 0 : alpha);

    }
    private record(type: ReplayInput['type'], source: string): void { this.inputs.push({ tick: this.gameplay.state.tick, type, source }); }
    private bridge(): any { return (globalThis as any).__GAME_AGENT_TEST__; }
    private publish(): void {
        this.bridge()?.setState?.('jumpAudio', this.audio?.snapshot());
        this.bridge()?.setState?.('jumpAudioEvents', this.audioEvents);
        const sources = this.node.getComponentsInChildren(AudioSource);
        this.bridge()?.setState?.('jumpAudioEngine', {
            sourceCount: sources.length,
            sources: sources.map(source => ({ name: source.node.name, playing: source.playing, loop: source.loop,
                volume: source.volume, currentTime: source.currentTime, duration: source.duration, clip: source.clip?.name })),
        });
        this.bridge()?.setState?.('jump', {
            configVersion: this.config.configVersion, ...this.gameplay.state,
            foot: this.gameplay.foot, holdSeconds: this.gameplay.holdSeconds,
            poolCount: this.pool?.count || 0, counts: { ...this.counts }, autoReplay: this.autoReplay,
        });
        this.bridge()?.setState?.('jumpUI', { page: this.singlePlayerUI?.currentPage, best: this.storage?.best || 0,
            storageKey: this.storage?.key, storageError: this.storage?.lastError, locked: this.transitionSeconds > 0,
            generation: this.uiGeneration, restartCount: this.restartCount, uiListeners: this.singlePlayerUI?.listenerCount,
            bootstrapCount: this.node.scene?.getComponentsInChildren(GameBootstrap).length });
        this.bridge()?.setState?.('jumpPlatforms', this.gameplay.platforms);
        this.bridge()?.setState?.('jumpResults', this.gameplay.results.slice(-32));
        this.bridge()?.setState?.('jumpInputs', this.inputs.slice(-32));
        this.bridge()?.setState?.('jumpView', {
            cameraPosition: this.worldCamera ? { x: this.worldCamera.position.x, y: this.worldCamera.position.y, z: this.worldCamera.position.z } : null,
            renderedFoot: this.avatar ? { x: this.avatar.position.x, y: this.avatar.position.y, z: this.avatar.position.z } : null,
            visualScaleY: this.avatarView?.visual?.scale.y,
        });
    }
}

import { DomainEvent, XZ } from '../core/types';

export const FEEDBACK_SECONDS = Object.freeze({ chargeEase: .08, launch: .12, landing: .18, center: .35, score: .45 });
const clamp = (v: number): number => Math.max(0, Math.min(1, v));
const age = (now: number, start: number | null): number => start === null ? Infinity : Math.max(0, now - start);
export interface FeedbackSample {
    readonly scaleXZ: number; readonly scaleY: number;
    readonly axisX: number; readonly axisZ: number; readonly flipRadians: number;
    readonly centerAlpha: number; readonly centerRadius: number; readonly scoreScale: number;
    readonly centerActive: boolean; readonly scoreActive: boolean;
}

/** No cc, wall-clock, timer, tween, random or rule writes. All time is simulation seconds. */
export class FeedbackTimeline {
    private runId = -1;
    private chargingAt: number | null = null;
    private launchAt: number | null = null;
    private landingAt: number | null = null;
    private centerAt: number | null = null;
    private scoreAt: number | null = null;
    private pausedAt: number | null = null;
    private flightTime = .6;
    private direction: XZ = { x: 1, z: 0 };
    // One monotonic id per event kind: bounded memory, even for very long runs.
    private lastJump = -1; private lastLanding = -1; private lastScore = -1;
    constructor(private readonly fixedStepSeconds = 1 / 60) {}
    reset(runId: number): void {
        this.runId = runId; this.chargingAt = this.launchAt = this.landingAt = this.centerAt = this.scoreAt = this.pausedAt = null;
        this.lastJump = this.lastLanding = this.lastScore = -1; this.direction = { x: 1, z: 0 };
    }
    clear(): void { this.reset(-1); }
    consume(event: DomainEvent, currentRunId: number): boolean {
        if (event.runId !== currentRunId) return false;
        if (event.type === 'Started') { if (this.runId === currentRunId) return false; this.reset(currentRunId); return true; }
        if (this.runId !== currentRunId) return false;
        const seconds = event.tick * this.fixedStepSeconds;
        switch (event.type) {
        case 'Charge': this.chargingAt = event.action === 'begin' ? seconds : null; break;
        case 'Jump':
            if (event.jumpId <= this.lastJump) return false;
            this.lastJump = event.jumpId; this.launchAt = seconds; this.landingAt = this.chargingAt = null;
            this.direction = { ...event.plan.directionXZ }; this.flightTime = event.plan.flightTime; break;
        case 'Landed':
            if (event.jumpId <= this.lastLanding) return false;
            this.lastLanding = event.jumpId; this.landingAt = seconds; this.launchAt = null; break;
        case 'Scored':
            if (event.jumpId <= this.lastScore) return false;
            this.lastScore = event.jumpId; this.scoreAt = seconds;
            this.centerAt = event.streak > 0 ? seconds : null; break;
        case 'Paused': this.pausedAt = seconds; this.chargingAt = null; break;
        case 'Resumed': this.pausedAt = null; break;
        case 'Failed': case 'Returned': this.reset(currentRunId); break;
        }
        return true;
    }
    sample(seconds: number, chargeRatio = 0, flightRatio: number | null = null, direction?: XZ): FeedbackSample {
        const now = this.pausedAt === null ? seconds : this.pausedAt;
        const charge = clamp(chargeRatio) * (this.chargingAt === null ? 1 : clamp(age(now, this.chargingAt) / FEEDBACK_SECONDS.chargeEase));
        const launchAge = age(now, this.launchAt), landAge = age(now, this.landingAt);
        const launch = launchAge < FEEDBACK_SECONDS.launch ? Math.sin(Math.PI * launchAge / FEEDBACK_SECONDS.launch) : 0;
        const land = landAge < FEEDBACK_SECONDS.landing ? Math.sin(Math.PI * landAge / FEEDBACK_SECONDS.landing) : 0;
        const spin = this.launchAt === null ? (flightRatio === null ? 0 : clamp(flightRatio)) : clamp(launchAge / this.flightTime);
        const dir = direction || this.direction, length = Math.hypot(dir.x, dir.z) || 1;
        const centerAge = age(now, this.centerAt), scoreAge = age(now, this.scoreAt);
        const centerActive = centerAge < FEEDBACK_SECONDS.center - 1e-9, scoreActive = scoreAge < FEEDBACK_SECONDS.score - 1e-9;
        return {
            scaleXZ: 1 + .12 * charge - .07 * launch + .10 * land,
            scaleY: 1 - .28 * charge + .18 * launch - .22 * land,
            axisX: dir.z / length, axisZ: -dir.x / length, flipRadians: spin * Math.PI * 2,
            centerAlpha: centerActive ? 1 - centerAge / FEEDBACK_SECONDS.center : 0,
            centerRadius: 12 + 24 * clamp(centerAge / FEEDBACK_SECONDS.center),
            scoreScale: scoreActive ? 1 + .20 * Math.sin(Math.PI * scoreAge / FEEDBACK_SECONDS.score) : 1,
            centerActive, scoreActive,
        };
    }
    get activeRunId(): number { return this.runId; }
}

/** Independent fixed visual sequence; never receives a platform PRNG. */
export class BackgroundSequence {
    private runId = -1; private scored = 0; private lastScore = -1;
    private readonly sequence = [5, 0, 1, 2, 3, 4, 6];
    reset(runId: number): void { this.runId = runId; this.scored = 0; this.lastScore = -1; }
    consume(event: DomainEvent, currentRunId: number): boolean {
        if (event.runId !== currentRunId) return false;
        if (event.type === 'Started') { if (this.runId === currentRunId) return false; this.reset(currentRunId); return true; }
        if (event.type === 'Returned') { this.reset(currentRunId); return true; }
        if (this.runId !== currentRunId || event.type !== 'Scored' || event.jumpId <= this.lastScore) return false;
        this.lastScore = event.jumpId; this.scored++; return true;
    }
    get index(): number { return this.sequence[Math.floor(this.scored / 4) % this.sequence.length]; }
}

import { _decorator, Component, Node, Quat } from 'cc';
import { DomainEvent, FootPosition, XZ } from '../core/types';
import { FeedbackTimeline } from './FeedbackTimeline';
const { ccclass, property } = _decorator;

/** Root is the logical foot. Only the Visual is animated; never read it for rules. */
@ccclass('AvatarView')
export class AvatarView extends Component {
    @property(Node) visual: Node | null = null;
    @property(Node) head: Node | null = null;
    @property(Node) body: Node | null = null;
    @property rawFootY = 0.0837;
    private readonly feedback = new FeedbackTimeline();
    private readonly rotation = new Quat();
    consume(event: DomainEvent, currentRunId: number): void { this.feedback.consume(event, currentRunId); }
    resetFeedback(runId: number): void {
        this.feedback.reset(runId);
        if (this.visual) {
            this.visual.setScale(1, 1, 1); this.visual.setRotationFromEuler(0, 0, 0);
            this.visual.setPosition(0, -this.rawFootY, 0);
        }
    }
    clear(): void { this.resetFeedback(-1); }
    onDestroy(): void { this.clear(); }
    // Existing four arguments remain valid. Stage04 uses simulation seconds and locked direction.
    render(foot: FootPosition, chargeRatio: number, flightRatio: number | null, topY: number,
        simulationSeconds = 0, direction?: XZ): void {
        this.node.setPosition(foot.x, foot.y, foot.z);
        if (this.visual) {
            const f = this.feedback.sample(simulationSeconds, chargeRatio, flightRatio, direction);
            this.visual.setScale(f.scaleXZ, f.scaleY, f.scaleXZ);
            const half = f.flipRadians / 2, sine = Math.sin(half);
            this.rotation.set(f.axisX * sine, 0, f.axisZ * sine, Math.cos(half));
            this.visual.setRotation(this.rotation);
            // Rotate scaled raw-foot compensation too: the pivot remains the logical foot.
            const offsetY = -this.rawFootY * f.scaleY, sin = Math.sin(f.flipRadians), cos = Math.cos(f.flipRadians);
            this.visual.setPosition(-f.axisZ * sin * offsetY, cos * offsetY, f.axisX * sin * offsetY);
        }
        const shadow = this.node.getChildByName('ContactShadow');
        if (shadow) {
            const height = Math.max(0, foot.y - topY);
            shadow.setPosition(0, topY - foot.y + 0.015, 0);
            shadow.setScale(0.18 / (1 + height * 0.1), 0.14 / (1 + height * 0.1), 1);
            shadow.active = foot.y >= topY;
            // No guessed uniform/shared-material mutation. Alpha requires verified renderer contract.
        }
    }
}

import { _decorator, Component, Node, Label, Button, Graphics, UITransform, Color, TTFFont, Camera, Vec3 } from 'cc';
import { Phase, DomainEvent, FootPosition } from '../core';
import { FeedbackTimeline } from './FeedbackTimeline';
const { ccclass, property } = _decorator;
export interface UIActions { start(): void; pause(): void; resume(): void; restart(): void; home(): void; }

/** Presentation only: page is derived from the single gameplay phase. No rule/controller copy. */
@ccclass('JumpUI')
export class JumpUI extends Component {
    @property(Node) homePage: Node | null = null;
    @property(Node) hudPage: Node | null = null;
    @property(Node) pausePage: Node | null = null;
    @property(Node) resultPage: Node | null = null;
    @property(Label) score: Label | null = null;
    @property(Label) hint: Label | null = null;
    @property(Label) resultScore: Label | null = null;
    @property(Label) bestScore: Label | null = null;
    @property(Label) storageNotice: Label | null = null;
    @property(TTFFont) numberFont: TTFFont | null = null;
    @property(Button) play: Button | null = null;
    @property(Button) pauseButton: Button | null = null;
    @property(Button) resumeButton: Button | null = null;
    @property(Button) pauseRestart: Button | null = null;
    @property(Button) pauseHome: Button | null = null;
    @property(Button) replay: Button | null = null;
    @property(Button) home: Button | null = null;
    // Optional editor-owned HUD child with Graphics + UITransform; never created at runtime.
    @property(Graphics) centerFlash: Graphics | null = null;
    @property(Camera) worldCamera: Camera | null = null;
    private readonly feedback = new FeedbackTimeline();
    private centerFoot: Vec3 | null = null;
    private scoreBase: Vec3 | null = null;
    private readonly projected = new Vec3();
    private bindings: Array<{ button: Button; callback: () => void }> = [];
    private page = '';
    private shadeSizes = new Map<Node, string>();
    connect(actions: UIActions): void {
        this.disconnect();
        if (!this.homePage || !this.hudPage || !this.pausePage || !this.resultPage || !this.numberFont ||
            !this.score || !this.resultScore || !this.bestScore ||
            !this.play || !this.pauseButton || !this.resumeButton || !this.pauseRestart || !this.pauseHome || !this.replay || !this.home)
            throw new Error('JumpUI phase03 references incomplete');
        this.scoreBase = this.score.node.scale.clone();
        for (const label of [this.score, this.resultScore, this.bestScore]) {
            label.useSystemFont = false; label.font = this.numberFont;
        }
        const pairs: Array<[Button, () => void]> = [[this.play, actions.start], [this.pauseButton, actions.pause],
            [this.resumeButton, actions.resume], [this.pauseRestart, actions.restart], [this.pauseHome, actions.home],
            [this.replay, actions.restart], [this.home, actions.home]];
        this.bindings = pairs.map(([button, callback]) => {
            button.node.on(Button.EventType.CLICK, callback, this); return { button, callback };
        });
    }
    disconnect(): void {
        for (const { button, callback } of this.bindings) button.node.off(Button.EventType.CLICK, callback, this);
        this.bindings = [];
        this.clearFeedback();
    }
    consume(event: DomainEvent, currentRunId: number, centerFoot?: FootPosition): void {
        if (!this.feedback.consume(event, currentRunId)) return;
        if (event.type === 'Started' || event.type === 'Returned' || event.type === 'Failed') {
            this.centerFoot = null; this.restoreScore(); this.centerFlash?.clear();
        } else if (event.type === 'Scored') {
            this.centerFoot = event.streak > 0 && centerFoot ? new Vec3(centerFoot.x, centerFoot.y, centerFoot.z) : null;
        }
    }
    resetFeedback(runId: number): void {
        this.feedback.reset(runId); this.centerFoot = null; this.restoreScore();
        if (this.centerFlash) { this.centerFlash.clear(); this.centerFlash.node.active = false; }
    }
    clearFeedback(): void { this.resetFeedback(-1); }
    private restoreScore(): void { if (this.score && this.scoreBase) this.score.node.setScale(this.scoreBase); }
    private renderFeedback(seconds: number): void {
        const f = this.feedback.sample(seconds);
        if (this.score && this.scoreBase) this.score.node.setScale(this.scoreBase.x * f.scoreScale, this.scoreBase.y * f.scoreScale, this.scoreBase.z);
        const flash = this.centerFlash;
        if (!flash) return;
        flash.clear();
        const parent = flash.node.parent;
        flash.node.active = !!(f.centerActive && this.centerFoot && this.worldCamera && parent && parent.getComponent(UITransform));
        if (!flash.node.active || !parent || !this.worldCamera || !this.centerFoot) return;
        this.worldCamera.convertToUINode(this.centerFoot, parent, this.projected);
        flash.node.setPosition(this.projected);
        flash.lineWidth = 3;
        flash.strokeColor = new Color(255, 255, 225, Math.round(235 * f.centerAlpha));
        flash.circle(0, 0, f.centerRadius); flash.stroke();
    }
    onDestroy(): void { this.disconnect(); }
    setLocked(locked: boolean): void { for (const { button } of this.bindings) button.interactable = !locked; }
    render(phase: Phase, score: number, best: number, firstJump: boolean, storageError: string | null, simulationSeconds = 0): void {
        this.renderFeedback(simulationSeconds);
        const page = phase === 'menu' ? 'home' : phase === 'paused' ? 'pause' : phase === 'gameover' ? 'result' : 'hud';
        if (page !== this.page) {
            this.page = page;
            if (this.homePage) this.homePage.active = page === 'home';
            if (this.hudPage) this.hudPage.active = page === 'hud';
            if (this.pausePage) this.pausePage.active = page === 'pause';
            if (this.resultPage) this.resultPage.active = page === 'result';
        }
        if (this.score) this.score.string = String(score);
        if (this.resultScore) this.resultScore.string = String(score);
        if (this.bestScore) this.bestScore.string = String(best);
        if (this.hint) this.hint.node.active = firstJump;
        if (this.storageNotice) this.storageNotice.string = storageError ? '最高分暂未保存，本次仍可继续' : '';
        for (const node of [this.homePage, this.pausePage, this.resultPage]) {
            if (!node?.activeInHierarchy) continue;
            const shade = node.getChildByName('Shade'), transform = shade?.getComponent(UITransform), graphics = shade?.getComponent(Graphics);
            if (!shade || !transform || !graphics) continue;
            const size = `${transform.width}:${transform.height}`;
            if (this.shadeSizes.get(shade) === size) continue;
            graphics.clear(); graphics.fillColor = new Color(25, 27, 31, node === this.homePage ? 75 : 175);
            graphics.rect(-transform.width / 2, -transform.height / 2, transform.width, transform.height); graphics.fill();
            this.shadeSizes.set(shade, size);
        }
    }
    get currentPage(): string { return this.page; }
    get listenerCount(): number { return this.bindings.length; }
}

import { Sprite, SpriteFrame, Texture2D } from 'cc';
import { DomainEvent } from '../core/types';
import { BackgroundSequence } from './FeedbackTimeline';

/** Owns seven runtime frames only. Source Texture2D assets/import settings are read-only. */
export class BackgroundView {
    private readonly sequence = new BackgroundSequence();
    private frames: SpriteFrame[] = [];
    private readonly original: SpriteFrame | null;
    private disposed = false;
    constructor(private readonly gradient: Sprite, textures: readonly Texture2D[]) {
        if (textures.length !== 7 || textures.some(t => !t)) throw new Error('BackgroundView needs gradient_0..6 Texture2D in numeric order');
        this.original = gradient.spriteFrame;
        this.frames = textures.map(texture => { const frame = new SpriteFrame(); frame.texture = texture; return frame; });
        this.reset(-1);
    }
    reset(runId: number): void { if (!this.disposed) { this.sequence.reset(runId); this.apply(); } }
    consume(event: DomainEvent, currentRunId: number): void {
        if (!this.disposed && this.sequence.consume(event, currentRunId)) this.apply();
    }
    private apply(): void { this.gradient.spriteFrame = this.frames[this.sequence.index]; }
    get index(): number { return this.sequence.index; }
    get ownedFrameCount(): number { return this.frames.length; }
    // Terminal cleanup, idempotent. Use reset() (not clear()) for home/newRun.
    clear(): void {
        if (this.disposed) return;
        this.disposed = true;
        if (this.frames.indexOf(this.gradient.spriteFrame!) >= 0) this.gradient.spriteFrame = this.original;
        for (const frame of this.frames) frame.destroy();
        this.frames = [];
    }
    destroy(): void { this.clear(); }
}

